import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SearchSuggestionSystem {

	public List<List<String>> suggestedProducts(String[] products, String searchWord) {
		Arrays.sort(products);
		int top = 0;
		int bottom = products.length - 1;
		List<List<String>> result = new ArrayList<>();
		for (int i=0; i<searchWord.length(); i++) {
			List<String> res = new ArrayList<>();
			while (top < products.length && (products[top].length() <= i || products[top].charAt(i) != searchWord.charAt(i))) {
				top++;
			}
			while (bottom > 0 && (products[bottom].length() <= i ||  products[bottom].charAt(i) != searchWord.charAt(i))) {
				bottom--;
			}
			if (top <= bottom) {
				int k = 0;
				while (k < 3 && k <= bottom - top) {
					res.add(products[k + top]);
					k++;
				}
			}
			result.add(res);
		}
		return result;
	}

	public static void main(String[] args) {
		// String[] products = new String[] {"mobile","mouse","moneypot","monitor","mousepad"};
		// String searchWord = "mouse";
		String[] products = new String[] {"","","",""};
		String searchWord = "";
		SearchSuggestionSystem solution = new SearchSuggestionSystem();
		List<List<String>> result = solution.suggestedProducts(products, searchWord);
		System.out.println(result);
	}
}
